    if x is None: return None
    s=x if isinstance(x,str) else json.dumps(x)
    return s if len(s)<=n else s[:n]+'...[len %d]'%len(s)
out=[]
for s in steps:
    out.append('===== step %s %s ====='%(s['step_id'],s['source']))
    if s.get('reasoning_content'): out.append('REASON: '+short(s['reasoning_content'],500))
    if s.get('message'): out.append('MSG: '+short(s['message'],500))
    for t in (s.get('tool_calls') or []):
        fn=t.get('function_name'); args=t.get('arguments')
        out.append('TOOL '+fn+': '+short(args,300))
    if s.get('observation') is not None:
        out.append('OBS: '+short(s['observation'],400))
open('/tmp/dump.txt','w').write('\n'.join(out))
print('written', len(out),'lines')
"', 'description': 'Write full readable dump'}

